<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import AdvancedLayout from '@/advanced/components/AdvancedLayout.vue'
import request from '@/utils/request'
import { useAuthStore } from '@/store/auth'
import { useLocaleStore } from '@/store/locale'
import { useMarketStore } from '@/store/market'
import { accountMode } from '@/utils/accountMode'
import marketWebSocket from '@/utils/marketWebSocket'
import { displaySymbol } from '@/utils/displaySymbol'
import { formatDateTime, getSystemTimezone } from '@/utils/dateTime'
import searchIcon from '@/advanced/assets/home-explore/search.svg'
import backIcon from '@/advanced/assets/home-explore/back.svg'
import depthPreviewBuy from '@/advanced/assets/home-explore/depth-preview-buy.svg'
import depthPreviewSell from '@/advanced/assets/home-explore/depth-preview-sell.svg'
import depthBuy from '@/advanced/assets/home-explore/depth-buy.svg'
import depthSell from '@/advanced/assets/home-explore/depth-sell.svg'
import traderEquity from '@/advanced/assets/home-explore/trader-equity.svg'
import traderDetailEquity from '@/advanced/assets/home-explore/trader-detail-equity.svg'

const route = useRoute(), router = useRouter(), locale = useLocaleStore(), auth = useAuthStore(), market = useMarketStore()
const text = (zh: string, en: string) => locale.text(zh, en)
const panels = ['overview', 'depth', 'calendar', 'radar', 'news', 'traders', 'trader-detail']
const panel = computed(() => panels.includes(String(route.query.panel)) ? String(route.query.panel) : '')
const designNodes: Record<string, string> = { '': '91:2235', overview: '37:2247', depth: '37:2315', calendar: '37:2373', radar: '37:2485', news: '37:2546', traders: '37:2611', 'trader-detail': '37:2723' }
const panelTitle = computed(() => ({ '': text('探索', 'Explore'), overview: text('行情概况', 'Market overview'), depth: text('市场深度', 'Market depth'), calendar: text('交易日历', 'Trading calendar'), radar: text('交易雷达', 'Trading radar'), news: text('新闻与公告', 'News & announcements'), traders: text('热门交易员', 'Featured traders'), 'trader-detail': text('交易员详情', 'Trader details') })[panel.value])
const symbols = ref<any[]>([]), categories = ref<{ key: string; label: string }[]>([]), marketLoading = ref(false), marketError = ref(''), category = ref('Crypto'), showAll = ref(false)
const fetchedAt = ref(0), now = ref(Date.now()), baseline = ref<Record<string, number>>({}), watched = ref<string[]>([])
const announcements = ref<any[]>([]), announcementsLoading = ref(false), announcementsError = ref(''), newsTab = ref('announcements'), openedAnnouncement = ref<string | number | null>(null)
const calendarFilter = ref('today'), calendarMonth = ref(new Date(2026, 9, 1)), calendarDay = ref(2), calendarExpanded = ref(''), reminders = ref<string[]>([])
const radarFilter = ref('all'), depthPaused = ref(true), traderSort = ref('overall')
const controller = new AbortController(), owner = auth.token
let disposed = false, refreshTimer: ReturnType<typeof setInterval> | undefined, newsGeneration = 0, lastRefresh = 0
const active = () => !disposed && auth.token === owner
const watchedKey = `advanced-watchlist:${location.host}:${auth.user?.tenantId || 'guest'}:${auth.user?.id || 'guest'}:${accountMode()}`
try { const list = JSON.parse(localStorage.getItem(watchedKey) || '[]'); if (Array.isArray(list)) watched.value = list.filter(s => typeof s === 'string') } catch { /* Unreadable preference never changes account state. */ }
const money = (value: unknown, precision = 2) => value === null || value === undefined || !Number.isFinite(Number(value)) ? '—' : Number(value).toLocaleString(locale.locale, { minimumFractionDigits: precision, maximumFractionDigits: precision })
const pct = (value: number | null) => value === null ? '—' : `${value > 0 ? '+' : ''}${money(value)}%`
const quoteStatus = (symbol: any) => market.getQuoteStatus(symbol.symbol, now.value)
const quotePrice = (symbol: any) => quoteStatus(symbol) === 'unavailable' ? null : market.getPrice(symbol.symbol) || null
const change = (symbol: any) => quoteStatus(symbol) === 'available' ? market.getChange24h(symbol.symbol).changePct : null
const quoteTime = computed(() => Math.max(0, ...symbols.value.map(symbol => market.quoteStatusMap[symbol.symbol]?.timestamp || 0)))
const time = (value: number) => value ? new Intl.DateTimeFormat(locale.locale, { timeZone: getSystemTimezone(), hour: '2-digit', minute: '2-digit', second: '2-digit' }).format(value) : '—'
const availableCategories = computed(() => [{ key: 'watched', label: text('自选', 'Watchlist') }, ...categories.value.filter(c => symbols.value.some(s => s.category === c.key)).map(c => ({ key: c.key, label: locale.categoryLabel(c.key, c.label) }))])
const filteredSymbols = computed(() => symbols.value.filter(s => category.value === 'watched' ? watched.value.includes(s.symbol) : s.category === category.value))
const visibleSymbols = computed(() => showAll.value || panel.value === 'overview' ? filteredSymbols.value : filteredSymbols.value.slice(0, 3))
const rising = computed(() => symbols.value.filter(s => (change(s) ?? 0) > 0).length), falling = computed(() => symbols.value.filter(s => (change(s) ?? 0) < 0).length)
const radarSymbols = computed(() => symbols.value.filter(s => radarFilter.value !== 'watched' || watched.value.includes(s.symbol)).map(s => {
  const price = quotePrice(s), start = baseline.value[s.symbol]
  return { symbol: s, change: price && start && quoteStatus(s) === 'available' ? (price - start) / start * 100 : null }
}).filter(s => radarFilter.value !== 'changed' || s.change !== null && Math.abs(s.change) >= .01).sort((a, b) => Math.abs(b.change || 0) - Math.abs(a.change || 0)).slice(0, 20))
const overviewSymbol = ref('')
const overviewSnapshot = computed(() => market.getHomeSparkline(overviewSymbol.value))
const overviewPath = computed(() => { const data = overviewSnapshot.value.points; if (!data.length) return ''; const low = Math.min(...data), high = Math.max(...data); return data.map((value, i) => `${i ? 'L' : 'M'}${(2 + i / Math.max(data.length - 1, 1) * 330).toFixed(2)},${(144 - (value - low) / Math.max(high - low, .000001) * 132).toFixed(2)}`).join(' ') })
const sampleTraders = [{ name: 'Atlas', return: 8.24, drawdown: 6.8, trades: 128 }, { name: 'Helix', return: 5.16, drawdown: 4.9, trades: 96 }, { name: 'North', return: 3.89, drawdown: 3.2, trades: 72 }]
const traders = computed(() => [...sampleTraders].sort((a, b) => traderSort.value === 'drawdown' ? a.drawdown - b.drawdown : b.return - a.return))
const trader = computed(() => sampleTraders.find(t => t.name === route.query.trader) || sampleTraders[0]!)
const sampleEvents = computed(() => [
  { id: 'nfp', title: text('非农就业人数', 'Nonfarm payrolls'), time: '20:30', day: 2 }, { id: 'unemployment', title: text('失业率', 'Unemployment rate'), time: '20:30', day: 2 }, { id: 'fomc', title: text('FOMC 会议纪要', 'FOMC meeting minutes'), time: '02:00', day: 7 },
].filter(event => calendarFilter.value === 'all' || calendarFilter.value === 'week' || event.day === calendarDay.value))
const monthLabel = computed(() => new Intl.DateTimeFormat(locale.locale, { year: 'numeric', month: 'long' }).format(calendarMonth.value))
const demoLabel = computed(() => text('原型演示 / 示例数据', 'Prototype demo / Sample data'))
async function loadMarkets() {
  if (marketLoading.value) return
  marketLoading.value = true
  try {
    const [data, categoryData]: any[] = await Promise.all([request.get('/market/all', { signal: controller.signal }), request.get('/market/categories', { signal: controller.signal })])
    if (!active()) return
    if (!Array.isArray(data?.list) || !Array.isArray(categoryData?.list)) throw new Error('Invalid market response')
    symbols.value = data.list.filter((s: any) => s.isEnabled !== false)
    categories.value = categoryData.list.filter((c: any) => c.enabled !== false)
    if (category.value !== 'watched' && !categories.value.some(c => c.key === category.value)) category.value = categories.value[0]?.key || 'Crypto'
    fetchedAt.value = Date.now(); marketError.value = ''
    if (!overviewSymbol.value && symbols.value.length) overviewSymbol.value = symbols.value[0].symbol
    await market.subscribeSymbols(symbols.value.map((s: any) => ({ symbol: s.symbol, category: s.category || 'Crypto', alltickSymbol: s.alltickSymbol })), 'advanced-explore')
    if (!active()) { marketWebSocket.release('advanced-explore'); return }
    void market.loadHomeSparklineSnapshot(symbols.value.map(s => s.symbol))
  } catch (error: any) { if (active()) marketError.value = error.message || text('行情加载失败', 'Market data unavailable') }
  finally { if (active()) marketLoading.value = false }
}
async function loadAnnouncements() {
  const generation = ++newsGeneration
  announcementsLoading.value = true
  try {
    const data: any = await request.get('/user/announcements', { params: { language: locale.locale }, signal: controller.signal })
    if (!active() || generation !== newsGeneration) return
    if (!Array.isArray(data?.announcements)) throw new Error('Invalid announcements response')
    announcements.value = data.announcements; announcementsError.value = ''
  } catch (error: any) { if (active() && generation === newsGeneration) announcementsError.value = error.message || text('公告加载失败', 'Announcements unavailable') }
  finally { if (active() && generation === newsGeneration) announcementsLoading.value = false }
}
function open(value: string, traderName?: string) { openedAnnouncement.value = null; void router.push({ path: '/explore', query: { ...(value ? { panel: value } : {}), ...(traderName ? { trader: traderName } : {}) } }) }
function trade(symbol: any) { if (symbol.isEnabled === false) return; void router.push({ path: '/trade', query: { symbol: symbol.symbol, category: symbol.category || 'Crypto' } }) }
function toggleWatch(symbol: string) { watched.value = watched.value.includes(symbol) ? watched.value.filter(s => s !== symbol) : [...watched.value, symbol]; try { localStorage.setItem(watchedKey, JSON.stringify(watched.value)) } catch { /* Watchlist remains usable for this session. */ } }
function shiftMonth(direction: number) { calendarMonth.value = new Date(calendarMonth.value.getFullYear(), calendarMonth.value.getMonth() + direction, 1) }
function reminder(id: string) { reminders.value = reminders.value.includes(id) ? reminders.value.filter(r => r !== id) : [...reminders.value, id] }
function refreshVisible() { if (document.visibilityState === 'visible') { lastRefresh = Date.now(); void loadMarkets(); void loadAnnouncements() } }
watch(() => market.priceMap, () => { const next = { ...baseline.value }; for (const symbol of symbols.value) if (!next[symbol.symbol] && quoteStatus(symbol) === 'available') next[symbol.symbol] = market.getPrice(symbol.symbol); baseline.value = next }, { deep: true })
watch(() => locale.locale, () => { void loadAnnouncements() })
onMounted(() => { refreshVisible(); refreshTimer = setInterval(() => { now.value = Date.now(); if (now.value - lastRefresh > 30000) refreshVisible() }, 1000); document.addEventListener('visibilitychange', refreshVisible) })
onBeforeUnmount(() => { disposed = true; newsGeneration++; controller.abort(); clearInterval(refreshTimer); marketWebSocket.release('advanced-explore'); document.removeEventListener('visibilitychange', refreshVisible) })
</script>

<template>
  <AdvancedLayout nav>
    <header class="explore-header" :class="{ detail: panel }"><button v-if="panel" type="button" class="icon-button" :aria-label="text('返回探索', 'Back to Explore')" @click="open(panel === 'trader-detail' ? 'traders' : '')"><img :src="backIcon" alt="" /></button><h1>{{ panelTitle }}</h1><button type="button" class="icon-button search-button" :aria-label="text('搜索行情', 'Search markets')" @click="router.push('/search')"><img :src="searchIcon" alt="" /></button></header>
    <div class="explore-content" :data-design-node="designNodes[panel]">
      <template v-if="!panel || panel === 'overview'">
        <p v-if="panel === 'overview'" class="notice">{{ text('仅统计平台覆盖品种；不伪装全市场市值、总成交额或 BTC 占比', 'Platform instruments only; not global market cap, volume, or BTC dominance.') }}</p>
        <section class="market-section"><div v-if="!panel" class="section-heading"><h2>{{ text('行情概况', 'Market overview') }}</h2><button type="button" class="text-button" @click="open('overview')">{{ text('总览', 'Overview') }} ›</button></div>
          <div class="metrics"><div><small>{{ text('覆盖品种', 'Instruments') }}</small><b>{{ marketError ? '—' : symbols.length }}</b></div><div><small>{{ text('上涨 / 下跌', 'Up / Down') }}</small><b>{{ rising }} / {{ falling }}</b></div><div><small>{{ text('报价时间', 'Quote time') }}</small><b>{{ time(quoteTime) }}</b></div></div>
          <p v-if="marketError" class="error" role="alert">{{ marketError }} <button type="button" @click="loadMarkets">{{ text('重试', 'Retry') }}</button></p>
          <div class="tabs categories"><button v-for="item in availableCategories" :key="item.key" type="button" :class="{ active: category === item.key }" :aria-pressed="category === item.key" @click="category = item.key">{{ item.label }}</button></div>
          <div v-for="symbol in visibleSymbols" :key="symbol.symbol" class="market-row"><button type="button" class="market-link" @click="trade(symbol)"><span>{{ displaySymbol(symbol) }}</span><span class="price">{{ money(quotePrice(symbol), symbol.pricePrecision ?? 2) }} <span :class="Number(change(symbol)) < 0 ? 'negative' : ''">{{ pct(change(symbol)) }}</span><small v-if="quoteStatus(symbol) !== 'available'" class="muted">{{ quoteStatus(symbol) === 'stale' ? text('已过期', 'Stale') : text('报价不可用', 'Quote unavailable') }}</small></span></button><button type="button" class="watch-button" :aria-pressed="watched.includes(symbol.symbol)" :aria-label="text('自选', 'Watchlist') + ' ' + displaySymbol(symbol)" @click="toggleWatch(symbol.symbol)">{{ watched.includes(symbol.symbol) ? '★' : '☆' }}</button></div>
          <p v-if="!visibleSymbols.length" class="empty">{{ marketLoading ? text('加载中', 'Loading') : text('暂无行情', 'No market data') }}</p><button v-if="!panel && filteredSymbols.length > 3" type="button" class="text-button all-markets" @click="showAll = !showAll">{{ showAll ? text('收起', 'Collapse') : text('全部品种', 'All instruments') }}</button>
        </section>
        <section v-if="panel === 'overview'" class="panel"><h2>{{ text('市场观察', 'Market watch') }}</h2><label class="muted">{{ text('单一品种真实快照 · 非全市场指数', 'Actual single-instrument snapshot · Not a global index') }}<select v-model="overviewSymbol"><option v-for="symbol in symbols" :key="symbol.symbol" :value="symbol.symbol">{{ displaySymbol(symbol) }}</option></select></label><svg v-if="overviewPath" class="overview-chart" viewBox="0 0 334 156" role="img" :aria-label="text('真实单一品种行情曲线', 'Actual single-instrument chart')"><path :d="overviewPath" fill="none" stroke="#56723e" stroke-width="1.5" /></svg><p v-else class="empty">{{ text('暂无曲线数据', 'No chart data') }}</p><p class="muted">{{ overviewSnapshot.status === 'fresh' ? text('真实行情快照', 'Actual market snapshot') : text('曲线暂不可用 / 已过期', 'Chart unavailable / stale') }} · {{ time(overviewSnapshot.updatedAt || 0) }}</p></section>
      </template>
      <template v-if="!panel">
        <section><div class="section-heading"><h2>{{ text('交易工具', 'Trading tools') }}</h2><button type="button" class="text-button" @click="open('overview')">{{ text('全部', 'All') }} ›</button></div><div class="tool-grid"><button type="button" @click="open('depth')"><small>{{ text('深度图', 'Depth chart') }}</small><b>{{ text('原型演示', 'Prototype demo') }}</b></button><button type="button" @click="open('calendar')"><small>{{ text('交易日历', 'Calendar') }}</small><b>{{ text('原型演示', 'Prototype demo') }}</b></button><button type="button" @click="open('radar')"><small>{{ text('交易雷达', 'Radar') }}</small><b>{{ text('会话报价', 'Session quotes') }}</b></button></div></section>
        <section><div class="section-heading"><h2>{{ text('市场深度', 'Market depth') }}</h2><button type="button" class="text-button" @click="open('depth')">{{ text('全部', 'All') }} ›</button></div><button type="button" class="panel full-card" @click="open('depth')"><div class="row"><b>BTCUSDT</b><small class="muted">{{ demoLabel }}</small></div><div class="depth-preview"><div><img :src="depthPreviewBuy" alt="" /></div><div><img :src="depthPreviewSell" alt="" /></div></div><div class="row"><small class="positive">{{ text('买盘累计', 'Cumulative bids') }}</small><small class="negative">{{ text('卖盘累计', 'Cumulative asks') }}</small></div></button></section>
        <section><div class="section-heading"><h2>{{ text('交易日历', 'Trading calendar') }}</h2><button type="button" class="text-button" @click="open('calendar')">{{ text('全部', 'All') }} ›</button></div><div class="panel"><span class="demo-badge">{{ demoLabel }}</span><button v-for="event in sampleEvents.slice(0, 2)" :key="event.id" type="button" class="event-preview" @click="open('calendar')"><span>{{ event.time }}</span><div><b>{{ event.title }}</b><small>{{ text('前值 — · 预期 — · 示例', 'Previous — · Forecast — · Sample') }}</small></div></button></div></section>
        <section><div class="section-heading"><h2>{{ text('交易雷达', 'Trading radar') }}</h2><button type="button" class="text-button" @click="open('radar')">{{ text('全部', 'All') }} ›</button></div><button type="button" class="panel full-card" @click="open('radar')"><div class="row"><b>{{ radarSymbols[0] ? displaySymbol(radarSymbols[0].symbol) : '—' }}</b><span class="accent">{{ pct(radarSymbols[0]?.change ?? null) }}</span></div><p class="muted">{{ text('基于本次会话真实报价变化；不含链上巨鲸事件', 'Derived from actual quotes in this session; no on-chain whale events.') }}</p></button></section>
        <section><div class="section-heading"><h2>{{ text('新闻与公告', 'News & announcements') }}</h2><button type="button" class="text-button" @click="open('news')">{{ text('全部', 'All') }} ›</button></div><p v-if="announcementsError" class="error" role="alert">{{ announcementsError }} <button type="button" @click="loadAnnouncements">{{ text('重试', 'Retry') }}</button></p><button v-else-if="announcements.length" type="button" class="panel full-card" @click="open('news')"><b>{{ announcements[0].title }}</b><p class="muted">{{ text('平台公告', 'Platform announcement') }} · {{ formatDateTime(announcements[0].displayAt || announcements[0].createdAt) }}</p></button><p v-else class="empty">{{ announcementsLoading ? text('加载中', 'Loading') : text('暂无平台公告', 'No announcements') }}</p></section>
        <section><div class="section-heading"><h2>{{ text('热门交易员', 'Featured traders') }}</h2><button type="button" class="text-button" @click="open('traders')">{{ text('全部', 'All') }} ›</button></div><button type="button" class="panel full-card" @click="open('trader-detail', 'Atlas')"><span class="demo-badge">{{ demoLabel }}</span><div class="row"><b>Atlas · {{ text('趋势策略', 'Trend strategy') }}</b><span class="accent">+8.24%</span></div><div class="metrics"><div><small>{{ text('最大回撤', 'Max drawdown') }}</small><b>6.8%</b></div><div><small>{{ text('交易次数', 'Trades') }}</small><b>128</b></div><div><small>{{ text('周期', 'Period') }}</small><b>{{ text('30日', '30D') }}</b></div></div><p class="accent">{{ text('查看示例曲线与历史仓位', 'View sample curve & positions') }} ›</p></button></section>
      </template>
      <template v-else-if="panel === 'depth'">
        <p class="notice">{{ demoLabel }} · {{ text('未接入真实订单簿，不用于交易决策', 'No live order book. Not for trading decisions.') }}</p><div class="row"><b>BTCUSDT</b><button class="text-button" type="button" :aria-pressed="!depthPaused" @click="depthPaused = !depthPaused">{{ depthPaused ? text('播放演示', 'Play demo') : text('暂停演示', 'Pause demo') }}</button></div><section class="panel"><h2>{{ text('买卖盘累计深度', 'Cumulative bid / ask depth') }}</h2><div class="depth-animation" :class="{ playing: !depthPaused }"><img :src="depthBuy" :alt="text('示例买盘曲线', 'Sample bids')" /><img :src="depthSell" :alt="text('示例卖盘曲线', 'Sample asks')" /></div><div class="metrics"><div><small>{{ text('买盘', 'Bids') }}</small><b class="positive">{{ text('演示', 'Demo') }}</b></div><div><small>{{ text('价差', 'Spread') }}</small><b>{{ text('演示', 'Demo') }}</b></div><div><small>{{ text('卖盘', 'Asks') }}</small><b class="negative">{{ text('演示', 'Demo') }}</b></div></div></section><p class="muted">{{ text('动画仅演示显示交互；数值不变、非实时数据', 'Animation previews presentation only; fixed sample data, not real time.') }}</p>
      </template>
      <template v-else-if="panel === 'calendar'">
        <p class="notice">{{ demoLabel }} · {{ text('实际事件源待接入；不会推送真实提醒', 'Event source not connected; no real notifications are scheduled.') }}</p><div class="tabs"><button v-for="filter in [{ key: 'today', label: text('选中日', 'Selected day') }, { key: 'week', label: text('本周', 'This week') }, { key: 'all', label: text('全部', 'All') }]" :key="filter.key" type="button" :class="{ active: calendarFilter === filter.key }" @click="calendarFilter = filter.key">{{ filter.label }}</button></div><div class="row"><span>{{ monthLabel }}</span><div><button class="month-button" type="button" :aria-label="text('上月', 'Previous month')" @click="shiftMonth(-1)">‹</button><button class="month-button" type="button" :aria-label="text('下月', 'Next month')" @click="shiftMonth(1)">›</button></div></div><div class="days"><button v-for="day in 7" :key="day" type="button" :class="{ active: calendarDay === day }" :aria-pressed="calendarDay === day" @click="calendarDay = day">{{ day }}</button></div><p class="muted">{{ text('示例事件重复用于预览筛选，不代表所选月份日程', 'Sample events preview filtering; they are not the selected month’s actual schedule.') }}</p><article v-for="event in sampleEvents" :key="event.id" class="panel"><div class="row"><h2>{{ event.title }}</h2><button type="button" class="text-button" :aria-expanded="calendarExpanded === event.id" @click="calendarExpanded = calendarExpanded === event.id ? '' : event.id">{{ calendarExpanded === event.id ? '−' : '+' }}</button></div><div class="row"><span>{{ text('时间 / 示例', 'Time / Sample') }}</span><b>{{ event.time }}</b></div><div class="metrics"><div v-for="label in [text('公布', 'Actual'), text('前值', 'Previous'), text('预期', 'Forecast')]" :key="label"><small>{{ label }}</small><b>—</b></div></div><div v-if="calendarExpanded === event.id"><p class="muted">{{ text('此卡仅展示宏观事件信息结构，无实际经济数据。', 'This card previews macro-event information structure without actual economic data.') }}</p><button type="button" class="secondary" @click="reminder(event.id)">{{ reminders.includes(event.id) ? text('取消示例提醒', 'Remove sample reminder') : text('添加示例提醒', 'Add sample reminder') }}</button><small class="muted">{{ text('仅本页状态；未创建通知', 'Page state only; no notification created') }}</small></div></article><p v-if="!sampleEvents.length" class="empty">{{ text('所选日期没有示例事件', 'No sample events on this day') }}</p>
      </template>
      <template v-else-if="panel === 'radar'">
